    "develop.paste" -> Lucide.ClipboardPaste
    "preset.delete" -> Lucide.Trash2
    "version.delete" -> Lucide.Trash2
    "pointColor.delete" -> Lucide.Trash2
    "mask.delete" -> Lucide.Trash2
    "mask.duplicate" -> Lucide.CopyPlus
    "spot.delete" -> Lucide.Trash2
    "redeye.delete" -> Lucide.Trash2
    "stack.group" -> Lucide.Group
